sql.where:
family_id = #{familyId}
AND date >= #{start}
AND date <= #{end}
AND openid = #{openid}

mapper.select:
SELECT category_name AS name, COALESCE(SUM(amount), 0) AS amount
FROM transaction
WHERE family_id = #{familyId}
AND date >= #{start}
AND date <= #{end}
AND type = 'expense'
GROUP BY category_name
ORDER BY amount DESC

SELECT t.openid,
       m.nickname AS nickname,
       COALESCE(SUM(CASE WHEN t.type = 'expense' THEN t.amount ELSE 0 END), 0) AS amount
FROM transaction t
LEFT JOIN family_member m ON m.family_id = t.family_id AND m.openid = t.openid AND m.status = 'active'
WHERE t.family_id = #{familyId}
AND t.date >= #{start}
AND t.date <= #{end}
GROUP BY t.openid, m.nickname
ORDER BY amount DESC
